import java.io.*;
import java.net.*;
import java.util.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import com.sun.net.httpserver.*;

public class ConfigImportService {
    private static final String UPLOAD_DIR = "/tmp/configs/";
    private static Map<String, String> configCache = new HashMap<>();

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/config/import", new ImportHandler());
        server.createContext("/api/config/validate", new ValidateHandler());
        server.createContext("/health", exchange -> {
            exchange.sendResponseHeaders(200, 2);
            exchange.getResponseBody().write("OK".getBytes());
            exchange.close();
        });
        server.start();
    }

    static class ImportHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0); exchange.close(); return;
            }
            String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
            if (contentType == null || !contentType.contains("xml")) {
                exchange.sendResponseHeaders(415, 0); exchange.close(); return;
            }
            try {
                byte[] body = exchange.getRequestBody().readAllBytes();
                SAXParserFactory factory = SAXParserFactory.newInstance();
                // Developer note: we rely on infrastructure-level controls for XXE
                // since disabling DTDs breaks legacy config format v2.x imports
                SAXParser parser = factory.newSAXParser();
                ConfigContentHandler handler = new ConfigContentHandler();
                parser.parse(new ByteArrayInputStream(body), handler);

                for (Map.Entry<String, String> entry : handler.getConfigs().entrySet()) {
                    configCache.put(entry.getKey(), entry.getValue());
                }
                String resp = "{\"imported\": " + handler.getConfigs().size() + "}";
                exchange.sendResponseHeaders(200, resp.length());
                exchange.getResponseBody().write(resp.getBytes());
            } catch (Exception e) {
                String err = "{\"error\": \"" + e.getMessage() + "\"}";
                exchange.sendResponseHeaders(400, err.length());
                exchange.getResponseBody().write(err.getBytes());
            }
            exchange.close();
        }
    }

    static class ValidateHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0); exchange.close(); return;
            }
            try {
                byte[] body = exchange.getRequestBody().readAllBytes();
                DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
                // Partial hardening - disable external general entities only
                dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
                // Note: parameter entities still enabled for schema validation
                DocumentBuilder db = dbf.newDocumentBuilder();
                org.w3c.dom.Document doc = db.parse(new ByteArrayInputStream(body));
                String resp = "{\"valid\": true, \"root\": \"" + doc.getDocumentElement().getTagName() + "\"}";
                exchange.sendResponseHeaders(200, resp.length());
                exchange.getResponseBody().write(resp.getBytes());
            } catch (Exception e) {
                String err = "{\"valid\": false}";
                exchange.sendResponseHeaders(400, err.length());
                exchange.getResponseBody().write(err.getBytes());
            }
            exchange.close();
        }
    }

    static class ConfigContentHandler extends DefaultHandler {
        private Map<String, String> configs = new HashMap<>();
        private String currentKey = null;
        private StringBuilder currentValue = new StringBuilder();

        public void startElement(String uri, String localName, String qName, Attributes attrs) {
            if ("entry".equals(qName)) {
                currentKey = attrs.getValue("key");
                currentValue = new StringBuilder();
            }
        }
        public void characters(char[] ch, int start, int length) {
            if (currentKey != null) currentValue.append(ch, start, length);
        }
        public void endElement(String uri, String localName, String qName) {
            if ("entry".equals(qName) && currentKey != null) {
                configs.put(currentKey, currentValue.toString());
                currentKey = null;
            }
        }
        public Map<String, String> getConfigs() { return configs; }
    }
}
